javascript 59-key cipher decoder:
```javascript
export function decodeCustom(str, codeMap) {
  let out = "", i = 0;
  while (i < str.length) {
    const pair = str.slice(i, i + 2).toLowerCase();
    if (codeMap.has(pair)) { out += codeMap.get(pair); i += 2; }
    else { out += str[i] === "_" ? " " : str[i]; i++; }
  }
  return out;
}
